extern s32 gSaveTotalSlots,gTrackMarkerSerial,sMenuCountdown; extern void *sBonusObjectTable[],*gTrackMarkerParents[]; void requestSound(s32); void initTimer(void *,s32,s32); void *lookupDataEntry(s32); void spawnCaptionMessage(s32,void *,void *,s32,s32,s32,s32,s32,s32,s32,s32); void requestEnemyDefChange(void *,s32,s32);
/* Starts a bonus scene actor: plays the cue sound, sets the countdown from the total save slots, and spawns its track marker and effect. */ void startBonusSceneActor(void *actor) { s8 *actorBytes=actor; void *bonusObj=sBonusObjectTable[actorBytes[0x182]]; void *markerEntry; requestSound(0x224); switch(gSaveTotalSlots) { default: initTimer(&sMenuCountdown,1,0); break; case 3: initTimer(&sMenuCountdown,2,0); break; case 4: initTimer(&sMenuCountdown,3,0); break; case 5: initTimer(&sMenuCountdown,3,30); break; case 6: initTimer(&sMenuCountdown,4,0); break; case 7: initTimer(&sMenuCountdown,4,30); break; case 8: initTimer(&sMenuCountdown,5,0); break; } actorBytes[0x32c]=1; gTrackMarkerSerial++; markerEntry=lookupDataEntry(0x6026); spawnCaptionMessage(0,gTrackMarkerParents[actorBytes[0x183]],markerEntry,-1,-1,1,0,0,0,0,0); *(s16 *)(actorBytes+0x1d8)=500; actorBytes[0x32f]=5; requestEnemyDefChange(bonusObj,0,0x26); }
